-- 语文积累本-高中与初中实虚词教材关系（统一目录结构）
-- 初高中数据共用同一张表，通过 version_id + volume_id 区分教材版本与分册。
CREATE TABLE IF NOT EXISTS `edu_chn_word_catalog` (
`id` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键',
`version_id` varchar(64) NOT NULL COMMENT '学校管理平台教材版本ID',
`version_name` varchar(512) DEFAULT NULL COMMENT '版本名称',
`volume_id` varchar(64) NOT NULL COMMENT '分册/书目ID',
`volume_name` varchar(512) DEFAULT NULL COMMENT '分册/书目名称',
`sense_id` int(10) NOT NULL COMMENT '词义ID，关联 edu_chn_word_sense.id',
`sort` int(10) NOT NULL DEFAULT '0' COMMENT '词表顺序',
`status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '0=草稿，1=上架',
`is_del` tinyint(2) NOT NULL DEFAULT '0' COMMENT '0=未删除，1=已删除',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (`id`),
KEY `version_id` (`version_id`),
KEY `volume_id` (`volume_id`),
KEY `idx_sense` (`sense_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='语文积累本-实虚词目录挂载';



START TRANSACTION;

ON DUPLICATE KEY UPDATE
`version_id` = VALUES(`version_id`),
`version_name` = VALUES(`version_name`),
`volume_id` = VALUES(`volume_id`),
`volume_name` = VALUES(`volume_name`),
`sense_id` = VALUES(`sense_id`),
`sort` = VALUES(`sort`),
`status` = VALUES(`status`),
`is_del` = VALUES(`is_del`);

COMMIT;
